        )
        assert normalized_hash == rule["normalized_sha256"]
        assert rule["source_rule_id"] == f"rule-{normalized_hash}"
    checks.append(
        {
            "label": "inventory span/hash/source_rule_id reconstruction",
            "status": "MATCH",
